import nodemailer from "nodemailer";

function getEmailConfig() {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT ? Number(process.env.SMTP_PORT) : undefined;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.EMAIL_FROM;

  if (!host || !port || !from) {
    throw new Error(
      "Email is not configured. Please set SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, and EMAIL_FROM."
    );
  }

  return {
    host,
    port,
    auth: user && pass ? { user, pass } : undefined,
    from,
  };
}

const transporter = (() => {
  try {
    const { host, port, auth } = getEmailConfig();
    return nodemailer.createTransport({
      host,
      port,
      secure: port === 465,
      auth,
    });
  } catch (error) {
    console.warn("Email transport not initialized:", (error as Error)?.message);
    return null;
  }
})();

export async function sendPasswordResetEmail({
  to,
  resetUrl,
}: {
  to: string;
  resetUrl: string;
}) {
  if (!transporter) {
    throw new Error("Email transport is not configured");
  }

  const { from } = getEmailConfig();

  await transporter.sendMail({
    from,
    to,
    subject: "Reset your SkinTrack password",
    text: [
      "You requested a password reset for your SkinTrack account.",
      "If you did not make this request, you can safely ignore this email.",
      "",
      "To reset your password, click the link below:",
      resetUrl,
      "",
      "This link will expire in 1 hour.",
    ].join("\n"),
    html: `
      <p>You requested a password reset for your SkinTrack account.</p>
      <p>If you did not make this request, you can safely ignore this email.</p>
      <p>
        <a href="${resetUrl}" target="_blank" rel="noreferrer">
          Reset your password
        </a>
      </p>
      <p>This link will expire in 1 hour.</p>
    `,
  });
}
